import java.io.*;
import java.util.*;

public final class CF_630_D2_E_V1 {
    static long powerMod(long b, long e, long m) {
        long x = 1;
        while (e > 0) {
            if ((e & 1) == 1)
                x = (b * x) % m;
            b = (b * b) % m;
            e >>= 1;
        }
        return x;
    }

    static void process() throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Integer.parseInt(st.nextToken());
        long m = Integer.parseInt(st.nextToken());
        int L = Integer.parseInt(st.nextToken());
        int R = Integer.parseInt(st.nextToken());

        long mod = 998244353;
        long inv2 = powerMod(2, mod - 2, mod);
        long diff = R - L + 1;
        long p1 = diff / 2;
        long p2 = diff - p1;
        long nm = n * m;
        long ans;

        if ((nm & 1) == 1) {
            ans = powerMod(diff, nm, mod);
        } else {
            long pp1 = diff;
            long pp2 = Math.abs(p1 - p2);
            long opt1 = powerMod(pp1, nm, mod);
            long opt2 = powerMod(pp2, nm, mod);
            long opt = (opt1 + opt2) % mod;
            opt = (opt * inv2) % mod;
            ans = opt;
        }

        System.out.println(ans);
        br.close();
    }

    public static void main(String[] args) throws Exception {
        process();
    }
}
